n=19
objs=[(3,6,8),(4,13,4),(12,14,1),(14,3,2),(10,8,None)]
# preserve input crosses, paint each colored plus's horizontal and vertical lines; overlapping strokes obey horizontal then vertical precedence.
out=[[0]*n for _ in range(n)]
for r,c,col in objs:
    if col is not None:
        for j in range(n): out[r][j]=col
for r,c,col in objs:
    if col is not None:
        for i in range(n): out[i][c]=col
# restore each original five-cell plus entirely
for r,c,col in objs:
    for rr,cc in ((r,c),(r-1,c),(r+1,c),(r,c-1),(r,c+1)):
        out[rr][cc]=3 if (rr,cc)!=(r,c) else (col if col is not None else 0)
import json
print(json.dumps(out,separators=(',',':')))

n=19
objs=[(3,6,8),(4,13,4),(12,14,1),(14,3,2),(10,8,None)]
base=[[0]*n for _ in range(n)]; owner={}
for idx,(r,c,col) in enumerate(objs):
    for rr,cc in ((r,c),(r-1,c),(r+1,c),(r,c-1),(r,c+1)):
        owner[(rr,cc)]=idx
        if (rr,cc)!=(r,c): base[rr][cc]=3
    if col is not None: base[r][c]=col
# Colored rays travel outward and stop at any other cross's 3-arm or center.
h=[[None]*n for _ in range(n)]; v=[[None]*n for _ in range(n)]
for idx,(r,c,col) in enumerate(objs):
    if col is None: continue
    for dr,dc,target in ((0,-1,h),(0,1,h),(-1,0,v),(1,0,v)):
        rr,cc=r+dr,c+dc
        while 0<=rr<n and 0<=cc<n:
            if (rr,cc) in owner and owner[(rr,cc)] != idx:
                break
            if (rr,cc) not in owner:
                target[rr][cc]=col
            rr+=dr; cc+=dc
# Vertically cast strokes overwrite horizontally at intersections.
out=[]
for r in range(n):
    row=[]
    for c in range(n):
        if base[r][c]!=0: value=base[r][c]
        elif v[r][c] is not None: value=v[r][c]
        elif h[r][c] is not None: value=h[r][c]
        else: value=0
        row.append(value)
    out.append(row)
import json
assert len(out)==19 and all(len(x)==19 for x in out)
print(json.dumps(out,separators=(',',':')))
# report colored stroke intersections as audit
print('rows:')
for r in range(n):
    if any(h[r]): print(r, ''.join(map(str,out[r])))

